<?php
require_once 'includes/functions.php';
$start = microtime(true);
$health = get_detailed_health();
$latency = (int)round((microtime(true) - $start) * 1000);
$online = ($health['status'] ?? '') === 'healthy' || !empty($health['ok']);
$bot = is_array($health['bot'] ?? null) ? $health['bot'] : [];
$metrics = is_array($health['metrics'] ?? null) ? $health['metrics'] : [];
$uptime = (int)($health['uptime_seconds'] ?? 0);
$uptimeText = $uptime > 0 ? floor($uptime/86400).'d '.floor(($uptime%86400)/3600).'h' : 'Unavailable';
$avatar = is_logged_in() ? user_avatar_url() : '';
?>
